vector<long long> divisors(long long n) {
    vector<long long> d;
    for (long long i = 1; i * i <= n; i++) if (n % i == 0) {
        d.push_back(i);
        if (i * i != n) d.push_back(n / i);
    }
    sort(d.begin(), d.end());
    return d;
}

