static List<Long> divisors(long n) {
    List<Long> d = new ArrayList<>();
    for (long i = 1; i * i <= n; i++) if (n % i == 0) {
        d.add(i);
        if (i * i != n) d.add(n / i);
    }
    Collections.sort(d);
    return d;
}

