func divisors(n int64) []int64 {
    var d []int64
    for i := int64(1); i*i <= n; i++ {
        if n%i == 0 {
            d = append(d, i)
            if i*i != n { d = append(d, n/i) }
        }
    }
    sort.Slice(d, func(i, j int) bool { return d[i] < d[j] })
    return d
}
